        return all(a[i] == 0 for i in range(3, n))
    else: 
        return False

def flip_positions(x, y, z, a):
    if z - y != y - x: 
        return False
    a[x], a[y], a[z] = 1 - a[x], 1 - a[y], 1 - a[z]
    return True

def describe_operations(n, a):
    if n <= 3 or not is_possible(n, a):
        return "NO"

    queue = deque(range(1, n, 1))
    remaining_flips = set()

    for i in range(1, n - 1, 3):
        z = i + 2
        if not any(flip_positions(i, j, k, a) for j in range(i + 1, z, 1) for k in range(j + 1, z + 1, 1)): 
            queue.append(z + 2)
    for _ in range(n - 2): 
        for i, num in enumerate(queue): 
            if num - 1 in remaining_flips: 
                queue.remove(num - 1)
                remaining_flips.remove(i - 1)
            else: 
