                adj[i][edge] = connected_edges[edge][0][0]
                adj[i][edge_color - 1] = edge
                adj[i][start_vertex] = repainted_color

    return adj

def connectivity(adj, start_vertex, end_vertex):
    queue = [(start_vertex,)]  # heap
    visited = [False] * len(adj)
    parent = [-1] * len(adj)
    visited[start_vertex] = True

    while queue:
