        if cur_ver == end_vertex:
            break

        for edge, child in adj[cur_ver[1]]:
            if not visited[child]:
                visited[child] = True
                parent[child] = cur_ver[0]
                heappush(queue, (cur_ver[0] + 1, child))

    return end_vertex == parent[end_vertex]

