import collections

def get_answer():
    n = int(input())
    heights = list(map(int, input().split()))
    queries = []

    for _ in range(int(input())):
        l, r = map(int, input().split())
        queries.append((l, r))

    def query_range(l, r):
        counting_planks = collections.Counter()
        non_matching = collections.Counter()

        for h in heights[l-1:r]:
            counting_planks[h] += 1

        matching_count = 0

        for h in heights:
            if 0 < h > counting_planks[h-1]:
                non_matching[h] += 1
            else:
                matching_count += non_matching[h] * counting_planks[h-1]
                for nh in heights[r+1:]:
                    non_matching[nh] -= 1

        return matching_count

    return [' '.join(str(i) for i in sorted((query_range(l, r) for l, r in queries))) for _ in range(len(queries))]

print("\n".join(get_answer()))  # Print answers with Standard Input format
