MOD = 10**9 + 7

def mod_inverse(num, MOD):
    """Returns the modular multiplicative inverse of num under modulo MOD."""
    for x in range(1, MOD):
        if (num * x) % MOD == 1:
            return x
    return -1  # This line is only reached if the modular inverse does not exist.

def count_valid_strings(binary_str, max_len):
    """Counts the number of valid integers k under the given constraints."""
    total_count = 0
    prev_digit = None
    for index, bit in enumerate(binary_str):
        if bit == '0':
            if prev_digit is not None and prev_digit == '0':
                total_count += (max_len - index) * prev_digit % MOD
        elif bit == '1':
            if prev_digit is None:
                prev_digit = 1
            else:
                total_count += (max_len - index) % MOD
        prev_digit = bit
    return total_count % MOD

