import math
from collections import defaultdict

def can_all_zero(n, a):
    """
    Check if it's possible to make the array all zeros.
    """
    odd_count = 0
    for i in a:
        if i == 1:
            odd_count += 1

    # If the odd count cannot be perfectly divided by 3, it's impossible
    if odd_count % 3 != 0:
        return False
    else:
        return True

def operations_to_zero(n, a):
    """
    Generate the operations required to make all elements zero.
    """
    store = defaultdict(list)
    dp = [[False] * (n + 1) for _ in range(10)]

    for i in range(n):
        for j in range(n):
            for k in range(n):
                if i < j or j < k:
                    continue

                    # Case 1: i, j, k form an arithmetic progression with a common difference
                    if (a[i] + a[j] + a[k]) % 2 == 0:
                        dp[len(store[a[i], a[j], a[k]])][k] = True

                    # Case 2: i, j, k form an arithmetic progression with n-kth position common difference
                    diff = k - i
                    if diff <= n - j: 
                        dp[len(store[a[i], a[j], a[k]]) + 1][j - diff] = True

    stk = [n]
    ans = []

    while stk:
        now = stk.pop()
        if now == 0:
            ans.append([n - 2 * now])
            continue

