                        stk.append(now + 1)
                        storage = storage + [now + 1]
                        break

            # Case 2: The new candidate can be formed as n minus the arithmetic progression with common difference of 2*n-k
            for i, c in enumerate(dp[now + 1]):
                if c and len(store[a[i], a[n - now - 1], a[n - 2 * now - 1 + i]]) != 0: 
                          stk.append(now + 2)
                          storage = storage + [now + 2]
                          break

    r = 0
    for l in ans:
        r += l

    if r != len(a):
