    graph = [[] for _ in range(k)]
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
    return graph

def dfs(vertex, parent, graph, colors, connected_components, connected):
    connected[vertex] = connected_components[k]
    for neighbor in graph[vertex]:
        if neighbor == parent:
            continue
        if not connected[neighbor]:
            dfs(neighbor, vertex, graph, colors, connected_components, connected)
    return connected[vertex]

def bipartite_fast_color(vertices, graph, colors, connected_components):
