from typing import List

def flip_to_zero(n: int, a: List[int]) -> bool:
    if n == 3:  # Base case
        return a[0] == 0  # Only one element, so the result depends on the value of the first element

    solution = []

    # Process three elements at a time
    for i in range(3):
        if flip_to_zero(n // 3 - 1, a[3*i:3*(i+1)]):
            solution.append([3*i+1, 3*i+2, 3*i+3])
        a = list(filter(lambda x: x != a[i], a))

    if not a:
        return True, len(solution)

    # Process last elements
    if flip_to_zero(n // 3 - (n%3), a):
        solution.append([n//3, n//3+1, n//3+2])
        return True, len(solution)

    return False, None

