import numpy as np

MOD = 10**9 + 7

def convert_degree_to_power(powers):
    # Convert powers of degree to power of x, where a_i = x^a_i
    power_degree = {}
    x = 1
    for i, p in enumerate(powers):
        power_degree[i + 1] = power_degree[x // p] + power_degree[x % p]
        x *= p
    return power_degree

def update_power(power_degree, i):
    power = power_degree.get(i + 1)
    if power is None:
        power_degree[i + 1] = i + 1
    elif power > 1:
        power -= 1
        power_degree[i + 1] = power
        for j in range(i + 1, -1, -1):
            power_degree[j] = power_degree[j] * power
            power %= MOD
        power_degree[i] = 1
    elif power == 1:
        power_degree[i + 1] +=  power_degree[i] & 1 
    else:
        power_degree.pop(i + 1)

def calculate_strength(power_degree):
    strength = 1
    for power in power_degree.values():
        if power > 1:
            strength %= MOD
            for _ in range(power):
                strength += 1
                strength %= MOD
    return strength

