def find_queen(grille: List[List[int]], queens: int, x: int, y: int) -> bool:
    # Function to find if a queen can be placed without overlapping
    for dy in range(min(y, queens), -1, -1):
        for dx in range(min(x, queens), -1, -1):
            if grille[y - dy][x - dx] == 1:
                return False
    return True

def solve_grille(N: int, M: int, X: List[List[int]]) -> int:
    # Flatten the list of queens
    queens = sorted(i for row in X for i in row if i > -1)
    if not queens:
        return -1

    # Recursively solve the problem
    def solve(queens, x, y, killed_in):
        if y == N:
            return True, killed_in
        for queen in range(queens[x]):
            if queens[x] - queen + 1 > N - y:
                return False, killed_in
            killed_in += abs(queens[x] - queen + 1)
        ans, kill = solve(X, x + 1 if y % 2 else x - 1, y + 1, killed_in)
        return ans and all(X[y][x] < queens[x] or ~ans or solve(X, x + 1 if y % 2 else x, y + 1, kill + queens[x] if x != 1 or ans else 0) for x in range(queens[x])), kill
    return solve([None] * N, 0, 0, 0)

def get_id_of_queen(N: int, X: List[List[int]]) -> int:
    X.sort(key=lambda y: -max(y))
    Y, suff, X1 = [], defaultdict(int), []
    X1.extend(X)
    for i in range(N):
        Y.append(bisect_left(X1, X[i], 0, len(X1)) + 1)
        X1[Y[i]] = i + 1
    if max(Y) <= 1:
        return X[Y[0]] if Y[0] else 0
